import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmInfCurso = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [curso, setCurso] = useState({
    nome: "",
    nivel: "",
    periodo: "",
    area: "",
    professor: null,
    alunos: [],
  });
  const [professor, setProfessor] = useState(null);

  useEffect(() => {
    const fetchCurso = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setCurso(dados);

          // Buscar informações do professor se existir (mantido como estava)
          if (dados.professorId) {
            const profResposta = await fetch(
              `http://localhost:5000/professores/${dados.professorId}`
            );
            if (profResposta.ok) {
              const profData = await profResposta.json();
              setProfessor(profData.utilizador);
            }
          }
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    fetchCurso();
  }, [id]);

  if (!curso) return <p className="text-center mt-4">Carregando...</p>;

  return (
    <div className="container mt-4">
      {/* ... (código anterior mantido igual) ... */}

      <div className="col-md-6">
        <h4 className="fw-bold">Professor</h4>
        {professor ? (
          <div>
            <p><strong>Nome:</strong> {professor.nome}</p>
          </div>
        ) : (
          <p>Nenhum professor associado</p>
        )}

        <h4 className="fw-bold mt-4">Alunos Inscritos</h4>
        {curso.alunos && curso.alunos.length > 0 ? (
          <ul className="list-group">
            {curso.alunos.map((aluno) => (
              <li key={aluno.id} className="list-group-item">
                {aluno.utilizador?.nome || 'Aluno sem nome cadastrado'}
              </li>
            ))}
          </ul>
        ) : (
          <p>Nenhum aluno inscrito</p>
        )}
      </div>
    </div>
  );
};

export default AdmInfCurso;
